mapper.select:
    	DECLARE @sql NVARCHAR(MAX);
		DECLARE @filePath NVARCHAR(255) = #{imagePath};
		DECLARE @fileExists INT;


			SET @filePath = REPLACE(@filePath, 'Z:\', 'E:\IMAGES\');



		EXEC xp_fileexist @filePath, @fileExists OUTPUT;

		IF @fileExists = 1
		BEGIN
			SET @sql = N'
			SELECT BulkColumn AS IMAGE_DATA 
			FROM OPENROWSET(BULK ''' + @filePath + ''', SINGLE_BLOB) AS ImageData;';

			EXEC sp_executesql @sql;
		END
		ELSE
		BEGIN

		    SELECT NULL AS IMAGE_DATA;
		END


DECLARE @FileExist TABLE (FileExists INT, FileIsDir INT, ParentDirExists INT);


DECLARE @BL_VALUE VARCHAR(20) = #{blNo}; 


DECLARE @Result TABLE (
    SERIAL INT,
    IMAGE_PATH VARCHAR(200),
    IMAGE_DATA VARBINARY(MAX),
    CREATED DATETIME,
    NUM INT
);


DECLARE cur CURSOR FOR


		SELECT SERIAL, IMAGE_PATH_SID, CREATED


		SELECT SERIAL, IMAGE_PATH_TOP, CREATED


FROM IMG_INFO
WHERE BL = @BL_VALUE;

DECLARE @SERIAL INT, @IMAGE_PATH VARCHAR(200), @CREATED DATETIME, @IMAGE_DATA VARBINARY(MAX), @NUM INT = 1;
DECLARE @sql NVARCHAR(MAX), @param NVARCHAR(500);

OPEN cur;
FETCH NEXT FROM cur INTO @SERIAL, @IMAGE_PATH, @CREATED;

WHILE @@FETCH_STATUS = 0
BEGIN

    DELETE FROM @FileExist;

		SET @IMAGE_PATH = REPLACE(@IMAGE_PATH, 'Z:\', 'E:\IMAGES\');

    INSERT INTO @FileExist
    EXEC xp_fileexist @IMAGE_PATH;


    IF (SELECT FileExists FROM @FileExist) = 1
    BEGIN

        SET @sql = N'SELECT @ImageData = BulkColumn FROM OPENROWSET(BULK ''' + @IMAGE_PATH + ''', SINGLE_BLOB) AS ImageData';
        SET @param = N'@ImageData VARBINARY(MAX) OUTPUT';

        EXEC sp_executesql @sql, @param, @ImageData = @IMAGE_DATA OUTPUT;

        INSERT INTO @Result
        VALUES (@SERIAL, @IMAGE_PATH, @IMAGE_DATA, @CREATED, @NUM);

        SET @NUM = @NUM + 1;
    END

    FETCH NEXT FROM cur INTO @SERIAL, @IMAGE_PATH, @CREATED;
END

CLOSE cur;
DEALLOCATE cur;


SELECT * FROM @Result;
